#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;
const int N = 1 << 20;
int modpow(int a, int b) {
  int res = 1;
  while (b) {
    if (b & 1) res = (1LL * res * a) % MOD;
    a = (1LL * a * a) % MOD;
    b >>= 1;
  }
  return res;
}
const int M = 21;
int n;
int f[N], g[N];
int prob[M][M];
int idx_left[N], idx_right[N];
int rev[N];
int matched[M];
int adj[M][M];
void compute(int *dp, vector<int> left, vector<int> right, vector<int> subgraphs, int *idx) {
  vector<pair<int,int>> edges;
  for (int x : left)
    for (int y : right)
      edges.emplace_back(x, y);
  int esz = edges.size();
  for (int mask = 0; mask < (1 << esz); ++mask) {
    int rate = 1;
    int newmask = 0;
    for (int i = 0; i < esz; ++i) {
      int u = edges[i].first, v = edges[i].second;
      if (mask & (1 << i)) {
        rate = (1LL * rate * prob[u][v]) % MOD;
        adj[u][v] = 1;
      } else {
        rate = (1LL * rate * (1 - prob[u][v])) % MOD;
        adj[u][v] = 0;
      }
      rate = (rate + MOD) % MOD;
    }
    for (int gr : subgraphs) {
      vector<int> perm, indices;
      for (int x : left) perm.push_back(x);
      for (int i = 0; i < n; ++i)
        if (gr & (1 << i))
          indices.push_back(i + n);
      bool found = false;
      sort(indices.begin(), indices.end());
      do {
        bool ok = true;
        for (int i = 0; i < (int)perm.size(); ++i)
          if (!adj[perm[i]][indices[i]]) { ok = false; break; }
        if (ok) { found = true; break; }
      } while (next_permutation(indices.begin(), indices.end()));
      if (found) newmask |= (1 << idx[gr]);
    }
    dp[newmask] = (dp[newmask] + rate) % MOD;
  }
}
int main() {
  ios_base::sync_with_stdio(false); cin.tie(NULL);
  cin >> n;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j) {
      cin >> prob[i][j + n];
      prob[i][j + n] = (1LL * prob[i][j + n] * modpow(100, MOD - 2)) % MOD;
    }
  if (n == 1) { cout << prob[0][1]; return 0; }
  int m1 = n / 2, m2 = n - m1;
  int cnt1 = 0, cnt2 = 0;
  vector<int> sub1, sub2;
  for (int mask = 0; mask < (1 << n); ++mask) {
    if (__builtin_popcount(mask) == m1) { idx_left[mask] = cnt1++; sub1.push_back(mask); }
    if (__builtin_popcount(mask) == m2) { idx_right[mask] = cnt2++; sub2.push_back(mask); }
  }
  for (int i = 0; i < (int)sub2.size(); ++i) {
    int mask = sub2[i];
    for (int big = 0; big < (1 << cnt2); ++big)
      if (big & (1 << i))
        rev[big] |= (1 << idx_left[(1 << n) - 1 - mask]);
  }
  vector<int> l1, l2, r;
  for (int i = n; i < n + n; ++i) r.push_back(i);
  for (int i = 0; i < m1; ++i) l1.push_back(i);
  for (int i = m1; i < n; ++i) l2.push_back(i);
  compute(f, l1, r, sub1, idx_left);
  compute(g, l2, r, sub2, idx_right);
  for (int i = 0; i < cnt1; ++i)
    for (int mask = 0; mask < (1 << cnt1); ++mask)
      if (mask & (1 << i))
        f[mask] = (f[mask] + f[mask ^ (1 << i)]) % MOD;
  long long ans = 0;
  for (int mask = 1; mask < (1 << cnt2); ++mask) {
    int w = (1 - f[(1 << cnt1) - 1 - rev[mask]] + MOD) % MOD;
    ans = (ans + 1LL * w * g[mask]) % MOD;
  }
  cout << ans;
  return 0;
}
